"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["63216"],{22651(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.etapa_processo.regra_de_consolidacao_fora_da_forma_humana","status":422,"titulo":"A regra de consolida\xe7\xe3o s\xf3 se aplica \xe0 etapa de avalia\xe7\xe3o humana"},"descricao":{"codigo":"uniplus.selecao.etapa_processo.regra_de_consolidacao_fora_da_forma_humana","requisitos":["UNI-REQ-0175"],"oQueAconteceu":["A etapa informou uma regra de consolida\xe7\xe3o, mas a forma de avalia\xe7\xe3o dela n\xe3o \xe9\\n`HUMANA`: \xe9 `OBJETIVA` ou est\xe1 em branco. A regra de consolida\xe7\xe3o diz como as notas\\nlan\xe7adas pelos avaliadores viram a nota da etapa. Na avalia\xe7\xe3o objetiva ningu\xe9m lan\xe7a\\nnota, e sem forma declarada o sistema n\xe3o sabe se h\xe1 avaliadores.","Por isso a forma ausente tamb\xe9m \xe9 recusada aqui: a regra s\xf3 \xe9 aceita quando a etapa diz,\\nna mesma grava\xe7\xe3o, que \xe9 de avalia\xe7\xe3o humana. A recusa vale j\xe1 na grava\xe7\xe3o, tamb\xe9m em\\nrascunho, e chega no array `errors[]`, no campo `regraConsolidacao` da etapa."],"comoResolver":["Escolha um dos dois caminhos:","- se a etapa \xe9 avaliada pela banca, declare `formaDeAvaliacao` como `HUMANA` e mantenha a\\n  regra (avalia\xe7\xe3o \xfanica, ou corre\xe7\xe3o independente com terceiro corretor por\\n  discrep\xe2ncia);\\n- se a etapa \xe9 objetiva, mantenha `OBJETIVA` e remova a regra de consolida\xe7\xe3o.","Se a resposta trouxer mais de uma viola\xe7\xe3o em `errors[]`, corrija todas antes de\\nreenviar."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Etapa processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);